static void cast_camera_targets(FILE* f){std::fputs(",\"screen_targets\":[",f);bool comma=false;auto* c=observed_camera;if(c&&c->m_width>0&&c->m_height>0)for(auto& b:mutation_bodies){if(b.ref.cpu||!body_valid(b.ref))continue;bool sphere=false;for(auto s:b.shapes)if(s.kind=="Sphere"&&b3Shape_GetUserData(s.id)==nullptr)sphere=true;if(!sphere)continue;b3Pos p=b3Body_GetPosition(b.ref.id);b3Vec3 rel=b3SubPos(p,c->DrawOrigin());Vec4 clip=MulMV4(c->Proj(),MulMV4(c->View(),MakeVec4(rel.x,rel.y,rel.z,1)));if(clip.w<=0)continue;float x=(.5f+.5f*clip.x/clip.w)*c->m_width,y=(.5f-.5f*clip.y/clip.w)*c->m_height;if(x<20||x>c->m_width-20||y<60||y>c->m_height-40)continue;if(comma)std::fputc(',',f);comma=true;std::fprintf(f,"{\"body\":[%u,%u,%u],\"pixel\":[%.9g,%.9g],\"camera_size\":[%d,%d],\"position\":",b.ref.id.index1,b.ref.id.generation,b.ref.id.world0,x,y,c->m_width,c->m_height);host_pos(f,p);std::fputc('}',f);}std::fputc(']',f);}
